function sharedAncestor(parent: number[], p: number, q: number): number {
  const depth = (x: number) => { let d = 0; while (parent[x] !== -1) { x = parent[x]; d++; } return d; };
  let a = p, b = q, da = depth(p), db = depth(q);
  while (da > db) { a = parent[a]; da--; }
  while (db > da) { b = parent[b]; db--; }
  while (a !== b) { a = parent[a]; b = parent[b]; }
  return a;
}

